{
  "spec_version": 1.0,
  "title": "Tính diện tích elip thiết diện của hình nón",
  "description": "Chương trình dựng hình và tính diện tích elip tạo bởi mặt phẳng cắt hình nón.",
  "memory_declarations": [
    {
      "name": "S",
      "type": "point3",
      "source_fact_id": "S_coords"
    },
    {
      "name": "O",
      "type": "point3",
      "source_fact_id": "O_coords"
    },
    {
      "name": "A",
      "type": "point3",
      "source_fact_id": "A_coords"
    },
    {
      "name": "cone",
      "type": "curved_solid",
      "source_fact_id": "cone_shape"
    },
    {
      "name": "plane_beta",
      "type": "plane3",
      "source_fact_id": "plane_beta_eq"
    },
    {
      "name": "E",
      "type": "ellipse3",
      "source_fact_id": "intersection_is_ellipse"
    },
    {
      "name": "dien_tich_E",
      "type": "float"
    }
  ],
  "statements": [
    {
      "kind": "declare_point",
      "target_var": "S",
      "at": [0, 0, 12],
      "label": "Đỉnh S của hình nón"
    },
    {
      "kind": "declare_point",
      "target_var": "O",
      "at": [0, 0, 0],
      "label": "Tâm đáy O của hình nón"
    },
    {
      "kind": "declare_point",
      "target_var": "A",
      "at": [6, 0, 0],
      "label": "Điểm A trên đường tròn đáy"
    },
    {
      "kind": "construct_curved_solid",
      "target_var": "cone",
      "curved_kind": "cone",
      "anchor": "O",
      "apex_or_top": "S",
      "rim_point": "A",
      "label": "Hình nón"
    },
    {
      "kind": "construct_plane_from_equation",
      "target_var": "plane_beta",
      "a": 1,
      "b": 0,
      "c": 1,
      "d": -9,
      "label": "Mặt phẳng (β)"
    },
    {
      "kind": "assign",
      "target_var": "E",
      "expr": {
        "kind": "intersect_plane_curved_ellipse",
        "solid": "cone",
        "plane": "plane_beta"
      },
      "label": "Đường elip (E)"
    },
    {
      "kind": "assign",
      "target_var": "dien_tich_E",
      "expr": {
        "kind": "measure",
        "quantity": "area",
        "of": "E"
      },
      "label": "Diện tích hình elip (E)"
    }
  ],
  "pedagogical_intent": "Bài toán này minh họa cách dựng hình nón, mặt phẳng và tìm thiết diện là một elip, sau đó tính diện tích của elip đó."
}
